nextflow.enable.dsl=2

include { getSingleInput } from '../functions/parameters.nf'
include { step_assembly__spades } from '../steps/step_assembly__spades'
workflow {
    assembled = step_assembly__spades(getSingleInput()).assembly
}

nextflow.enable.dsl=2

include { getSingleInput; getReference } from '../functions/parameters.nf'
include { extractKey } from '../functions/common.nf'
include { step_mapping__bwa_mem2 } from '../steps/step_mapping__bwa_mem2'
workflow {
    reads = getSingleInput()
    reference = getReference('fa')
    reads.cross(reference) { extractKey(it) }
        .multiMap {
            reads: it[0]
            refs:  it[1][1..3]
        }
        .set { ch }
    step_mapping__bwa_mem2(ch.reads, ch.refs)
}

